def lora_total_trainable_params(num_layers: int, d: int, r: int, matrices_per_layer: int) -> int:
    per_matrix = r * (d + d)
    return num_layers * matrices_per_layer * per_matrix

def full_finetune_params(num_layers: int, d: int, matrices_per_layer: int) -> int:
    return num_layers * matrices_per_layer * d * d

def lora_trainable_percentage(num_layers: int, d: int, r: int, matrices_per_layer: int) -> float:
    """Percent of full fine-tuning's parameter count that LoRA actually trains."""
    lora_total = lora_total_trainable_params(num_layers, d, r, matrices_per_layer)
    full_total = full_finetune_params(num_layers, d, matrices_per_layer)
    return round(lora_total / full_total * 100, 4)

print(lora_trainable_percentage(32, 4096, 8, 4))
